"""Version 2 additions, transcribed from MAIB PDF pages.

Page numbers are physical PDF pages (1-based), not printed page numbers.
Safety Digest vessels are anonymous: the case key identifies an event, not a
real vessel name. Pride of Canterbury is counted once; SD 1/2016 case 12 is a
second description of that same accident and is not added as another case.
"""

SD13 = "MAIB_2013_Safety_Digest_lubrication_bearing_cases.pdf"
SD16 = "MAIB_2016_Safety_Digest_generator_oil_fire.pdf"
QM2 = "MAIB_2011_28_Queen_Mary_2_harmonic_filter_failure.pdf"
STENA = "MAIB_2024_20_Stena_Europe_fuel_spray_fire.pdf"
PRIDE = "MAIB_2015_22_Pride_of_Canterbury_CPP_hydraulic_fire.pdf"


def fact(a, relation, b, page, anchor, certainty="reported"):
    return (a, relation, b, page, anchor, certainty)


def case(key, title, vessel, vessel_type, source, page, anchor, subsystems,
         equipment, assets, facts, anonymous=True):
    return dict(id=key, name=title, vessel=vessel, vessel_type=vessel_type,
                system=None if anonymous else ("柴油机机械推进系统" if key != "queen_mary2_hf_2010" else "柴油发电-电力推进系统"),
                source=source, summary_page=page, summary_anchor=anchor,
                subsystems=subsystems, anonymous=anonymous, equipment=equipment,
                assets=assets, facts=facts)


